// Pointer lock is requested only by the caller's explicit control button.
export function groundControls(canvas,game,clear,onPause){
 const settings={sensitivity:.0025,invert:false,fov:80,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,quality:'normal',mute:false,contrast:false,bindings:{forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD',jump:'Space',sprint:'ShiftLeft',reload:'KeyR',fire:'KeyF',turnLeft:'ArrowLeft',turnRight:'ArrowRight',lookUp:'ArrowUp',lookDown:'ArrowDown'}};
 const keys=new Set(),touch=new Map();let drag=null,stick=null,fire=false,shown=false,lastPointerType='';addEventListener('pointerdown',e=>{lastPointerType=e.pointerType;},{capture:true});addEventListener('touchstart',()=>{lastPointerType='touch';},{capture:true,passive:true});
 const panel=document.createElement('details');panel.id='ground-settings';panel.innerHTML=`<summary>Ground settings</summary><label>Sensitivity <input name="sensitivity" type="range" min="0.001" max="0.008" step="0.0005" value="0.0025"></label><label>FOV <input name="fov" type="range" min="60" max="110" value="80"></label><label>Invert Y <input name="invert" type="checkbox"></label><label>Bob / shake <input name="motion" type="checkbox"></label><label>Mute <input name="mute" type="checkbox"></label><label>High contrast <input name="contrast" type="checkbox"></label><label>Graphics <select name="quality"><option value="normal">Normal</option><option value="low">Reduced</option></select></label><p>Click a binding, then press a key.</p><div id="bindings"></div>`;document.body.append(panel);panel.querySelector('[name=motion]').checked=settings.motion;
 const keyLabel=code=>code.replace(/^(Key|Digit)/,'');
 let binding=null;for(const [name,code] of Object.entries(settings.bindings)){const b=document.createElement('button');b.dataset.binding=name;b.textContent=`${name}: ${keyLabel(code)}`;b.onclick=()=>{if(game.state==='playing')pause();binding={name,b};b.textContent='Press a key';};panel.querySelector('#bindings').append(b);}
 panel.querySelector('summary').addEventListener('click',()=>{if(!panel.open&&game.ground&&game.state==='playing')pause();});panel.addEventListener('toggle',()=>{if(panel.open&&game.ground&&game.state==='playing')pause();});panel.oninput=e=>{const name=e.target.name;if(name in settings)settings[name]=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;};
 const ui=document.createElement('div');ui.id='ground-touch';ui.innerHTML=`<div id="move-stick" aria-label="Movement stick"><span>MOVE</span></div><div id="look-pad" aria-label="Drag to look">LOOK</div><div class="ground-actions"><button data-ground="fire">FIRE</button><button data-ground="jump">JUMP</button><button data-ground="reload">RELOAD</button><button data-ground="sprint">SPRINT</button></div>`;document.body.append(ui);
 function active(){return game.ground&&game.state==='playing'&&!game.scene&&!panel.open;}
 function release(){if(binding){binding.b.textContent=`${binding.name}: ${keyLabel(settings.bindings[binding.name])}`;binding=null;}keys.clear();touch.clear();if(game.ground)game.ground.player.jumpQueued=false;drag=null;stick=null;aim=null;fire=false;clear();}
 function pause(){release();if(game.state==='playing')game.pause();if(document.pointerLockElement===canvas)document.exitPointerLock();onPause();}
 function look(dx,dy){if(active())game.ground.look(dx*settings.sensitivity,-dy*settings.sensitivity*(settings.invert?-1:1));}
 addEventListener('keydown',e=>{
  if(!game.ground)return;
  if(e.code==='Escape'){e.preventDefault();pause();return;}
  if(binding){e.preventDefault();const old=settings.bindings[binding.name];for(const [name,code] of Object.entries(settings.bindings))if(name!==binding.name&&code===e.code){settings.bindings[name]=old;panel.querySelector(`[data-binding="${name}"]`).textContent=`${name}: ${keyLabel(old)}`;}settings.bindings[binding.name]=e.code;binding.b.textContent=`${binding.name}: ${keyLabel(e.code)}`;binding=null;return;}
  if(e.target.matches('input,select,button')||!active())return;
  if(Object.values(settings.bindings).includes(e.code)){e.preventDefault();keys.add(e.code);if(e.code===settings.bindings.reload)game.ground.reload();if(e.code===settings.bindings.jump&&!e.repeat)game.ground.player.jumpQueued=true;}
 });addEventListener('keyup',e=>keys.delete(e.code));
 canvas.addEventListener('pointerdown',e=>{if(!active()||e.pointerType==='touch')return;if(document.pointerLockElement===canvas){if(e.button===0)fire=true;}else{drag={id:e.pointerId,x:e.clientX,y:e.clientY};if(e.isTrusted)canvas.setPointerCapture(e.pointerId);}});
 canvas.addEventListener('pointermove',e=>{if(document.pointerLockElement===canvas)look(e.movementX,e.movementY);else if(drag?.id===e.pointerId){look(e.clientX-drag.x,e.clientY-drag.y);drag.x=e.clientX;drag.y=e.clientY;}});
 const end=e=>{if(drag?.id===e.pointerId)drag=null;if(e.type!=='pointerup'||e.button===0)fire=false;};for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,end);
 document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&active())pause();});document.addEventListener('pointerlockerror',()=>{release();document.querySelector('#status').textContent=`Pointer lock unavailable. Drag LOOK; use FIRE or ${keyLabel(settings.bindings.fire)} to shoot. Arrow keys turn.`;});
 addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});addEventListener('orientationchange',()=>{if(game.ground)pause();});screen.orientation?.addEventListener('change',()=>{if(game.ground)pause();});
 const capture=(el,down,move,up)=>{el.addEventListener('pointerdown',e=>{if(!active())return;e.preventDefault();canvas.focus({preventScroll:true});if(e.isTrusted)el.setPointerCapture(e.pointerId);down(e);});el.addEventListener('pointermove',move);for(const type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,up);};
 capture(ui.querySelector('#move-stick'),e=>{if(!stick)stick={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0};},e=>{if(stick?.id===e.pointerId){stick.dx=Math.max(-1,Math.min(1,(e.clientX-stick.x)/42));stick.dy=Math.max(-1,Math.min(1,(e.clientY-stick.y)/42));}},e=>{if(stick?.id===e.pointerId)stick=null;});
 let aim=null;capture(ui.querySelector('#look-pad'),e=>{if(!aim)aim={id:e.pointerId,x:e.clientX,y:e.clientY};},e=>{if(aim?.id===e.pointerId){look(e.clientX-aim.x,e.clientY-aim.y);aim.x=e.clientX;aim.y=e.clientY;}},e=>{if(aim?.id===e.pointerId)aim=null;});
 for(const b of ui.querySelectorAll('button'))capture(b,e=>{touch.set(e.pointerId,b.dataset.ground);if(b.dataset.ground==='reload')game.ground.reload();if(b.dataset.ground==='jump')game.ground.player.jumpQueued=true;},()=>{},e=>touch.delete(e.pointerId));
 return {settings,release,pause,async take(event){release();panel.open=false;canvas.focus({preventScroll:true});if(game.state==='paused')game.pause();if(event?.pointerType==='touch'||lastPointerType==='touch'||!matchMedia('(pointer: fine)').matches)return;try{const result=canvas.requestPointerLock?.();if(result?.then)await result;}catch{document.querySelector('#status').textContent=`Drag to look; FIRE / ${keyLabel(settings.bindings.fire)} shoots. Arrow keys turn.`;}},input(){const b=settings.bindings,v=[...touch.values()];return {forward:Number(keys.has(b.forward))-Number(keys.has(b.back))-(stick?.dy||0),side:Number(keys.has(b.right))-Number(keys.has(b.left))+(stick?.dx||0),turn:Number(keys.has(b.turnRight))-Number(keys.has(b.turnLeft)),pitchTurn:Number(keys.has(b.lookUp))-Number(keys.has(b.lookDown)),fire:fire||keys.has(b.fire)||v.includes('fire'),jump:false,reload:keys.has(b.reload)||v.includes('reload'),sprint:keys.has(b.sprint)||v.includes('sprint')};},show(value){ui.hidden=!value;panel.hidden=!value;if(shown&&!value)release();shown=value;}};
}
